script.setup:
// hydra-synth runs its own WebGL (regl) on a canvas that is never attached to the page. Each frame the
// scene ticks it, copies its canvas into a texture and draws that. Hydra also takes an existing canvas
// as a source: s0 is a 2D canvas the scene draws (moving type), which the "Type" patch feeds through Hydra.
const mod = await ctx.utils.import("https://esm.sh/hydra-synth@1.4.0");
const Hydra = mod.default ?? mod;
const [w, h] = ctx.resolution, H = 540, W = Math.round((H * w) / h);
const canvas = document.createElement("canvas");
canvas.width = W; canvas.height = H;
const hydra = new Hydra({ canvas, width: W, height: H, makeGlobal: false, autoLoop: false, detectAudio: false, enableStreamCapture: false });
// a canvas element (regl does not take an OffscreenCanvas as texture data), never attached
const type = document.createElement("canvas");
type.width = W; type.height = H;
const tc = type.getContext("2d");
const S = hydra.synth, u = () => ctx.uniforms;
const mx = () => ctx.mouse[0], my = () => ctx.mouse[1];
const PATCHES = [
  // kaleidoscope of oscillators, warped by noise; the pointer sets the warp
  () => S.osc(() => 10 + u().u_freq * 60, 0.06, 1.3).kaleid(6).color(0.9, 0.5, 1.2)
    .rotate(() => S.time * 0.08).modulate(S.noise(2.5, 0.2), () => 0.03 + mx() * 0.12)
    .modulateScale(S.osc(4, 0.05), () => 0.1 * my()).out(S.o0),
  // feedback tunnel: a spinning rainbow ring plus the last frame, scaled up and turned
  () => S.shape(4, 0.24, 0.01).diff(S.shape(4, 0.2, 0.01)).rotate(() => S.time * 0.4).mult(S.osc(6, 0.2, 2))
    .add(S.src(S.o0).scale(() => 1.02 + u().u_freq * 0.06).rotate(() => (mx() - 0.5) * 0.3).mult(S.solid(0.9, 0.9, 0.9)))
    .out(S.o0),
  // voronoi cells multiplied by color bands
  () => S.voronoi(() => 4 + u().u_freq * 16, 0.4, 0.3).mult(S.osc(8, 0.05, 2).hue(() => mx()))
    .modulatePixelate(S.noise(3, 0.1), 60, () => 8 + my() * 40).saturate(1.6).out(S.o0),
  // the scene's own 2D canvas as a Hydra source
  () => S.osc(8, 0.05, 1.4).rotate(0.5)
    .mult(S.src(S.s0).modulate(S.noise(() => 2 + u().u_freq * 6, 0.25), () => 0.01 + mx() * 0.08))
    .blend(S.src(S.o0).scale(1.012).rotate(0.003), 0.8).out(S.o0),
];
const gl = ctx.gl, tex = gl.createTexture();
gl.bindTexture(gl.TEXTURE_2D, tex);
for (const [k, v] of [[gl.TEXTURE_MIN_FILTER, gl.LINEAR], [gl.TEXTURE_MAG_FILTER, gl.LINEAR], [gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE], [gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE]]) gl.texParameteri(gl.TEXTURE_2D, k, v);
const fs = `#version 300 es
precision highp float;
in vec2 v_uv; out vec4 outColor;
uniform sampler2D u_hydra; uniform float u_split; uniform float u_mirror;
void main() {
  vec2 uv = vec2(u_mirror > 0.5 ? 0.5 - abs(v_uv.x - 0.5) : v_uv.x, 1.0 - v_uv.y);
  // a small chromatic split around the center
  vec2 dir = (uv - 0.5) * u_split * 0.02;
  vec3 c = vec3(texture(u_hydra, uv + dir).r, texture(u_hydra, uv).g, texture(u_hydra, uv - dir).b);
  c *= 1.0 - 0.35 * dot(v_uv - 0.5, v_uv - 0.5) * 2.0;
  outColor = vec4(c, 1.0);
}`;
Object.assign(ctx.state, { hydra, S, type, tc, PATCHES, tex, canvas, patch: -1, W, H,
  p: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, fs) });

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms;
const patch = Math.max(0, Math.min(s.PATCHES.length - 1, u.u_patch | 0));
// hush() also clears the sources, so s0 is attached again after it
if (patch !== s.patch) { s.patch = patch; s.S.hush(); s.S.s0.init({ src: s.type, dynamic: true }); s.PATCHES[patch](); ctx.publish("patch", patch); }
if (patch === 3) {
  // the 2D source Hydra reads as s0
  const { tc, W, H } = s, t = ctx.time;
  tc.fillStyle = "#000"; tc.fillRect(0, 0, W, H);
  tc.fillStyle = "#fff"; tc.textAlign = "center"; tc.textBaseline = "middle";
  tc.font = `900 ${Math.round(H * 0.24)}px Helvetica Neue, Arial, sans-serif`;
  tc.fillText("HYDRA", W / 2 + Math.sin(t * 0.7) * W * 0.08, H * 0.4);
  tc.font = `700 ${Math.round(H * 0.1)}px Helvetica Neue, Arial, sans-serif`;
  tc.fillText("in siljangnim", W / 2 - Math.sin(t * 0.7) * W * 0.08, H * 0.66);
  for (let i = 0; i < 5; i++) { tc.beginPath(); tc.arc(W * (0.1 + 0.2 * i), H * (0.5 + 0.38 * Math.sin(t + i)), H * 0.04, 0, Math.PI * 2); tc.fill(); }
}
// Tick Hydra and copy its frame right away (its drawing buffer is not preserved).
s.S.speed = u.u_speed;
s.hydra.tick(Math.min(ctx.dt, 0.1) * 1000);
gl.bindTexture(gl.TEXTURE_2D, s.tex);
gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, s.canvas);
gl.useProgram(s.p);
ctx.utils.bindTexture(s.p, "u_hydra", s.tex, 0);
ctx.utils.drawFullscreen(s.p, { u_split: u.u_split, u_mirror: u.u_mirror ? 1 : 0 });
